const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');const {createCanvas,ImageData,Image,loadImage}=require('@napi-rs/canvas');
const root=path.resolve(__dirname,'..'),out=path.join(root,'发型素材/07-猫耳栗棕双辫-生图试稿');global.window=global;global.ImageData=ImageData;global.Image=Image;global.document={createElement(){return Object.assign(createCanvas(1,1),{style:{}});}};global.FileReader=class{async readAsText(b){this.result=await b.text();this.onload();}};for(const n of ['core','canvas','export'])vm.runInThisContext(fs.readFileSync(path.join(root,'js',n+'.js'),'utf8'));
async function decode(url){const image=await loadImage(url),canvas=createCanvas(image.width,image.height);canvas.getContext('2d').drawImage(image,0,0);return canvas.getContext('2d').getImageData(0,0,image.width,image.height);}
async function run(){const api='http://127.0.0.1:8765/api/project?id=',raw=await fetch(api+'character-cat-braids-imagegen-20261029').then(r=>r.text()),main=await fetch(api+'main').then(r=>r.json()),ex=new PE.ExportManager(),p=(await ex.importProject(new Blob([raw]))).project,cm=new PE.CanvasManager(document.createElement('canvas'),p);ex.init(p,cm);p.currentSheetIndex=8;p.currentActionIndex=1;p.currentFrameIndex=0;
 const art=p.layers.filter(l=>l.name.includes('/ 07 '));assert.equal(art.length,5);for(const l of art){assert.equal(l.frameData.size,1);assert(l.frameData.has('8_1_0'));assert(l.frameData.get('8_1_0').data.some((v,i)=>i%4===3&&v===255));assert([...l.frameData.get('8_1_0').data].every((v,i)=>i%4!==3||v===0||v===255));}
 let unchanged=0;for(const l of main.layers.filter(l=>!l.isGroup&&(/^(body|head)$/.test(l.name)||PE.isHandLayer(l))))for(const [key,fd]of Object.entries(l.frameData||{})){const copy=p.layers.find(c=>c.name===l.name&&c.sheetIndex===l.sheetIndex&&c.frameData.has(key));assert(copy,'missing base '+l.name+' '+key);assert.deepEqual(copy.frameData.get(key).data,(await decode(fd.dataURL)).data,'base pixels changed '+l.name+' '+key);unchanged++;}
 const expected=cm.getCompositeImageData(8,1,0,true);cm.hideHands=false;cm.zoom=4;cm.offsetX=cm.offsetY=0;cm.canvas.width=cm.canvas.height=128;cm.showGrid=false;cm.render();assert.deepEqual(cm.offscreenCtx.getImageData(0,0,32,32).data,expected.data,'actual render loop differs from compositor');
 const png=await ex.exportFrameAsBlob(8,1,0),img=await loadImage(Buffer.from(await png.arrayBuffer())),cv=createCanvas(32,32);cv.getContext('2d').drawImage(img,0,0);assert.deepEqual(cv.getContext('2d').getImageData(0,0,32,32).data,expected.data,'transparent PNG differs from render');fs.writeFileSync(path.join(out,'export-front-32.png'),Buffer.from(await png.arrayBuffer()));
 const original=JSON.parse(fs.readFileSync(path.join(out,'source-main.json')));const worn=original.layers.filter(l=>l.sheetIndex===8&&l.name.startsWith('服装 /')&&l.frameData?.['8_1_0']);let clothingLayers=0;
 if(worn.length){const family=worn[0].name.split(' / ')[1];for(const l of worn.filter(l=>l.name.split(' / ')[1]===family)){const copy=new PE.Layer(l.name);copy.sheetIndex=8;copy.frameData.set('8_1_0',await decode(l.frameData['8_1_0'].dataURL));p.layers.push(copy);clothingLayers++;}const d=cm.getCompositeImageData(8,1,0,true),tile=createCanvas(32,32);tile.getContext('2d').putImageData(d,0,0);const big=createCanvas(512,512),ctx=big.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.fillStyle='#f4e9e9';ctx.fillRect(0,0,512,512);ctx.drawImage(tile,0,0,512,512);fs.writeFileSync(path.join(out,'clothing-compatibility-preview.png'),big.toBuffer('image/png'));}
 fs.writeFileSync(path.join(out,'verification.json'),JSON.stringify({baseFramesUnchanged:unchanged,separateArtworkLayers:art.length,onlyTargetFrame:'8_1_0',noSemiTransparentEdges:true,actualRenderMatchesComposite:true,exportMatchesRender:true,clothingPreviewLayers:clothingLayers},null,2));console.log('PASS',JSON.stringify({unchangedBaseFrames:unchanged,layers:art.length,renderAndExportMatch:true,clothingLayers}));
}
run().catch(e=>{console.error(e);process.exitCode=1;});
